<?php namespace App\Integrations\AI; use App\Integrations\Contract\AIProviderInterface; final class ConfiguredAIProvider implements AIProviderInterface{public function complete(string $prompt,array $context=[]):array{$cfg=require APP_ROOT.'/config/integrations.example.php';return (!$cfg['ai']['enabled']||!$cfg['ai']['endpoint']||!$cfg['ai']['api_key'])?['status'=>'disabled']:['status'=>'adapter_ready','endpoint'=>$cfg['ai']['endpoint'],'model'=>$cfg['ai']['model']];}}